package localchat;
import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import javax.swing.*;
public final class RecoveryFinalTest {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static Tools tools(Path root){return new Tools(new Tools.Context(root,root.resolve("skills"),root.resolve("rules.md"),root.resolve("settings.properties"),Map.of(),null,new Mcp(),PathMap.none(),true,EnumSet.allOf(Tools.Access.class),(a,b)->Tools.Decision.NO),Skills.load(root.resolve("skills")));}
 public static void main(String[] args)throws Exception{
  Path root=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-");Files.createDirectories(root.resolve("skills/demo"));Files.writeString(root.resolve("skills/demo/SKILL.md"),"---\nname: demo\ndescription: Fixture\n---\nProcedure");
  for(boolean stream:List.of(false,true)){
   var empty=stream?FeatureTest.sse(FeatureTest.event(Json.obj("choices",List.of(Json.obj("delta",Json.obj("reasoning_content","internal only")))))+"data: [DONE]\n\n"):FeatureTest.json(FeatureTest.answer("",20,5));
   try(var server=new FeatureTest.Server(DiscoveryRecoveryTest.skill("a"),DiscoveryRecoveryTest.skill("b"),DiscoveryRecoveryTest.skill("c"),DiscoveryRecoveryTest.skill("d"),empty)){
    Agent a=new Agent(tools(root));AtomicInteger notices=new AtomicInteger();a.run(Provider.CUSTOM,server.url(),"","fixture","fixture","system",List.of(ChatClient.Message.user("Compare actual import files")),stream,new Agent.Ui(){public void text(String s){}public void step(){}public void toolStarted(ChatClient.ToolCall c){}public void toolFinished(ChatClient.ToolCall c,Tools.Result r){}public void discoveryRecovery(boolean last){notices.incrementAndGet();}});
    var messages=a.collect("","fixture");var last=messages.get(messages.size()-1);check(server.requests.size()==5&&notices.get()==2,"empty recovery has bounded requests and phase notifications");check(a.recoveryIncomplete()&&last.role.equals("assistant")&&last.label.equals("LocalChat")&&!ReasoningDisplay.answer(last.content).isBlank(),"empty provider result becomes visible local partial notice");check(last.content.contains("read_skill")&&messages.stream().filter(m->m.role.equals("tool")).count()==4,"last repeated call and original tool pairs preserved");
   }
  }
  var replies=new ArrayList<FeatureTest.Response>();for(String id:List.of("a","b","c"))replies.add(DiscoveryRecoveryTest.skill(id));for(int i=0;i<6;i++){Files.createDirectories(root.resolve("folder"+i));replies.add(InteractionRecoveryTest.reply("",InteractionRecoveryTest.call("inventory"+i,"list_dir",Json.obj("path","folder"+i))));}replies.add(FeatureTest.json(FeatureTest.answer("Partial comparison; remaining catalogue check",10,3)));
  try(var server=new FeatureTest.Server(replies.toArray(FeatureTest.Response[]::new))){Agent a=new Agent(tools(root));a.run(Provider.CUSTOM,server.url(),"","fixture","fixture","system",List.of(ChatClient.Message.user("Compare")),false,ToolProtocolTest.ui(new AtomicInteger()));check(server.requests.size()==10&&a.recoveryIncomplete(),"six additional requests maximum before partial final");check(Json.get(server.requests.get(9),"tools")==null||Json.get(server.requests.get(9),"tools") instanceof List<?> list&&list.isEmpty(),"recovery budget final has no operational tools");}
  try(var server=new FeatureTest.Server(DiscoveryRecoveryTest.skill("a"),DiscoveryRecoveryTest.skill("b"),DiscoveryRecoveryTest.skill("c"),DiscoveryRecoveryTest.skill("d"),InteractionRecoveryTest.reply("",InteractionRecoveryTest.call("denied","write_file",Json.obj("path","never-after-final.txt","content","NO"))))){
   Agent a=new Agent(tools(root));a.run(Provider.CUSTOM,server.url(),"","fixture","fixture","system",List.of(ChatClient.Message.user("Compare")),false,ToolProtocolTest.ui(new AtomicInteger()));var messages=a.collect("","fixture");check(!Files.exists(root.resolve("never-after-final.txt"))&&messages.get(messages.size()-1).label.equals("LocalChat"),"hallucinated tool in final is not executed and cannot hide local notice");check(messages.stream().anyMatch(m->"denied".equals(m.toolCallId)&&m.isError),"denied final call paired in original archive");
  }
  LocalChat[] app={null};try(var server=new FeatureTest.Server(DiscoveryRecoveryTest.skill("a"),DiscoveryRecoveryTest.skill("b"),DiscoveryRecoveryTest.skill("c"),DiscoveryRecoveryTest.skill("d"),FeatureTest.json(FeatureTest.answer("",10,2)))){
   FeatureTest.edt(()->{Path home=root.resolve("app");Files.createDirectories(home.resolve("skills/demo"));Files.writeString(home.resolve("skills/demo/SKILL.md"),Files.readString(root.resolve("skills/demo/SKILL.md")));app[0]=AttachmentTest.window(home,server.url());AttachmentTest.state(app[0]).queuePaused=false;});NormalModeTest.ask(app[0],"Read the demo procedure and finish the check");FeatureTest.edt(()->{check(FeatureTest.<String>field(app[0],"statusKey").equals("Rezultat partial: modelul nu a incheiat verificarea ceruta."),"UI does not report Gata after blank recovery");check(AttachmentTest.state(app[0]).queuePaused,"partial recovery suspends explicit message queue");check(NormalModeTest.history(app[0]).stream().anyMatch(m->m.label!=null&&m.label.equals("LocalChat")&&m.content.contains("read_skill")),"local notice persisted in actual chat");app[0].dispose();});
  }finally{FeatureTest.edt(()->{for(var window:java.awt.Window.getWindows())window.dispose();});}
  System.out.println("PASS: "+checks+" recovery final/budget checks; JSON, SSE, actual UI and no external inference");System.exit(0);
 }
}
